import React from "react"
import complywise from "../../images/platform/complywise.svg"

export default function ComplyWiseHero() {
  return (
    <div className="saas-solution-area ptb-40">
      <div className="container">
        <div className="row align-items-center">
          <div className="col-lg-6 col-md-12">
            <div className="saas-solution-content text-center text-lg-start">
              <h1>ComplyWise Global</h1>
              <h3>AI-Powered GST Compliance Platform</h3>
              <p>
                ComplyWise Global simplifies GST compliance for CA firms and tax
                professionals with AI-powered notice management, GST return
                filing, and multi-client compliance tracking. Manage GST
                notices, track filing status, and file GSTR-1 for multiple
                clients from one unified platform—reducing manual effort and
                streamlining compliance workflows.
              </p>

              <div className="solution-btn">
                <a
                  href="https://complywise.global/"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="default-btn"
                >
                  <i className="flaticon-right mr-4"></i>Learn More
                  <span></span>
                </a>
              </div>
            </div>
          </div>

          <div className="col-lg-6 col-md-12">
            <div className="saas-solution-image">
              <img
                src={complywise}
                alt="ComplyWise Global - GST Notice Management"
                className="rounded"
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
